}

// Width, depth and height, to a tenth of a millimetre.
json bed_mm(const Workspace::BedSize& bed)
{
    const auto round = [](double x) { return std::round(x * 10.0) / 10.0; };
    return json::array({round(bed.width), round(bed.depth), round(bed.height)});
}

void add_loaded_object_facts(const Workspace::LoadedObjectFacts& facts, json& row, bool& truncated)
{
    row["placedOnBed"]     = facts.placed_on_bed;
    row["fitsSelectedBed"] = facts.fits_selected_bed;
    json fits = json::array();
    for (const std::string& name : facts.fits_setup_printers)
        if (fits.size() < 32)
            fits.push_back(label(name, truncated));
    row["fitsSetupPrinters"] = std::move(fits);
    json mesh{{"triangles", facts.triangles}, {"shells", facts.shells}, {"openEdges", facts.open_edges},
              {"repairedErrors", facts.repaired_errors}};
    if (!facts.units_suspicion.empty())
        mesh["unitsSuspicion"] = facts.units_suspicion;
    row["mesh"] = std::move(mesh);
    if (!facts.customizations.empty())
        row["customized"] = facts.customizations;
}

// Only what the file states; every value came from it.
json loaded_file_facts_result(const Workspace::LoadedFileFacts& facts, bool& truncated)
{
    json result{{"file", label(facts.file, truncated)}};
    if (!facts.application.empty())
        result["application"] = label(facts.application, truncated);
    if (!facts.printer_model.empty() || facts.nozzle_mm > 0) {
        json made_for = json::object();
        if (!facts.printer_model.empty())
            made_for["printerModel"] = label(facts.printer_model, truncated);
        if (facts.nozzle_mm > 0)
            made_for["nozzleMm"] = facts.nozzle_mm;
        result["madeFor"] = std::move(made_for);
    }
    json filaments = json::array();
    for (const auto& filament : facts.filaments)
        if (filaments.size() < 32)
            filaments.push_back({{"type", label(filament.type, truncated)}, {"colour", label(filament.colour, truncated)}});
    if (!filaments.empty())
        result["filaments"] = std::move(filaments);
    return result;
}

json selected_setup_change(const Workspace::LoadSelectedSetup& before,
                           const Workspace::LoadSelectedSetup& after, bool& truncated)
{
    json change = json::object();
    if (before.printer_preset != after.printer_preset)
        change["printerPreset"] = {{"from", label(before.printer_preset, truncated)},
                                   {"to", label(after.printer_preset, truncated)}};
    if (before.filament_preset != after.filament_preset)
        change["filamentPreset"] = {{"from", label(before.filament_preset, truncated)},
                                    {"to", label(after.filament_preset, truncated)}};
    if (before.process_preset != after.process_preset)
        change["processPreset"] = {{"from", label(before.process_preset, truncated)},
                                   {"to", label(after.process_preset, truncated)}};
    return change;
}

} // namespace

json load_report_result(const Workspace::LoadReport& report)
{
    bool truncated = false;
    json loads = json::array();
    for (const Workspace::FileLoadRecord& load : report.loads) {
        // A tool's safety net records what Orca asked outside any load.
        if (load.files.empty())
            continue;
        json files = json::array();
        for (const std::string& file : load.files)
            files.push_back(bounded(file, 1024, truncated));
        loads.push_back({{"files", std::move(files)}, {"withSettings", load.with_settings}});
    }
    json result{{"startedBy", report.started_by_agent ? "agent" : "user"},
                {"projectOpened", report.project_opened},
                {"uiLanguage", report.ui_language},
                {"loads", std::move(loads)},
                {"messages", orca_messages_result(report)},
                {"objects", objects_section_result(report.objects)}};
    json setup_printers = json::array();
    for (const Workspace::LoadSetupPrinter& printer : report.setup_printers) {
        if (setup_printers.size() == 32) {
            truncated = true;
            break;
        }
        json row{{"name", label(printer.name, truncated)}, {"model", label(printer.model, truncated)},
                 {"nozzleMm", printer.nozzle_mm}};
        if (printer.bed.width > 0)
            row["bedMm"] = bed_mm(printer.bed);
        setup_printers.push_back(std::move(row));
    }
    result["setupPrinters"] = std::move(setup_printers);
    if (report.selected_bed.width > 0)
        result["selectedPrinterBedMm"] = bed_mm(report.selected_bed);
    // The app's own checks of each loaded object, beside its row.
    for (json& row : result["objects"]["items"])
        for (const Workspace::LoadedObjectFacts& facts : report.object_facts)
            if (row["objectId"] == std::to_string(facts.id.value()))
                add_loaded_object_facts(facts, row, truncated);
    json file_facts = json::array();
    for (const Workspace::LoadedFileFacts& facts : report.file_facts)
        file_facts.push_back(loaded_file_facts_result(facts, truncated));
    if (!file_facts.empty())
        result["fileFacts"] = std::move(file_facts);
    result["setupPrintersTruncated"] = report.setup_printers.size() > 32;
    if (!report.connected_printer.empty())
        result["connectedPrinter"] = label(report.connected_printer, truncated);
    const bool settings_applied = std::any_of(report.loads.begin(), report.loads.end(),
                                             [](const Workspace::FileLoadRecord& load) { return load.settings_applied; });
    const bool is_3mf = std::any_of(report.loads.begin(), report.loads.end(), [](const Workspace::FileLoadRecord& load) {
        return std::any_of(load.files.begin(), load.files.end(), [](const std::string& file) {
            if (file.size() < 4) return false;
            std::string extension = file.substr(file.size() - 4);
            std::transform(extension.begin(), extension.end(), extension.begin(),
                           [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
            return extension == ".3mf";
        });
    });
    result["loadFacts"] = {{"settingsOutcome", settings_applied ? "applied" :
                                                  is_3mf ? (report.objects.empty() ? "not_applied" : "geometry_only") :
                                                           "not_applicable"},
                           {"selectedSetupBefore", selected_load_setup_result(report.selected_setup_before, truncated)},
                           {"selectedSetupAfter", selected_load_setup_result(report.selected_setup_after, truncated)},
                           {"selectedSetupChange", selected_setup_change(report.selected_setup_before,
                                                                           report.selected_setup_after, truncated)}};
    result["objects"]["truncated"] = result["objects"]["truncated"].get<bool>() || report.objects_truncated;
    if (!report.project_path.empty())
        result["projectPath"] = report.project_path;
    if (report.project_opened) {
        result["details"]     = project_details_fields(report.details, truncated);
        result["attachments"] = project_attachments(report.details, truncated);
    }
    result["truncated"] = truncated;
    return result;
}

namespace {
json vector3(const Workspace::Vec3& value)
{
    // Tenths of a micron: enough for any printer, and stable in a transcript.
    // `+ 0.0` turns a rounded -0 into 0.
    const auto round = [](double x) { return std::round(x * 10000.0) / 10000.0 + 0.0; };
    return json::array({round(value[0]), round(value[1]), round(value[2])});
}
} // namespace

json objects_section_result(const std::vector<Workspace::ObjectDetails>& objects)
{
    bool truncated = false;
    json items = json::array();
    for (const auto& object : objects) {
        if (items.size() == kToolListLimit) { truncated = true; break; }
        json plates = json::array();
        for (const auto& plate : object.plates) plates.push_back(std::to_string(plate.value()));
        json row{{"objectId", std::to_string(object.id.value())}, {"name", label(object.name, truncated)},
                 {"plateIds", std::move(plates)}, {"instanceCount", object.instances}, {"partCount", object.parts},
                 {"modifierCount", object.modifiers}, {"negativePartCount", object.negative_parts},
                 {"supportVolumeCount", object.support_volumes}, {"printable", object.printable},
                 {"sizeMm", vector3(object.size)}, {"overrideCount", object.overrides}};
        if (object.extruder > 0) row["extruder"] = object.extruder;
        if (!object.printable) row["printableInstanceCount"] = object.printable_instances;
        items.push_back(std::move(row));
    }
    return {{"items", std::move(items)}, {"truncated", truncated}};
}

json region_result(const Workspace::RegionRecord& record, const Workspace::RegionStatus* status)
{
    bool truncated = false;
    json artifacts = json::array();
    for (const Workspace::RegionArtifact& artifact : record.artifacts)
        if (artifacts.size() < 8)
            artifacts.push_back(text(Workspace::region_artifact_words(artifact), truncated));
    json result{{"regionId", record.id}, {"kind", record.kind}, {"label", text(record.label, truncated)},
                {"geometry", record.geometry.type}, {"artifacts", std::move(artifacts)}};
    if (status) {
        if (status->object)
            result["objectId"] = std::to_string(status->object->value());
        result["bindingLost"]      = status->binding_lost;
        result["artifactsMissing"] = status->artifacts_missing;
    } else {
        result["objectId"] = std::to_string(record.object);
    }
    return result;
}

json object_analysis_result(Workspace::ObjectId id, const Workspace::ObjectAnalysis& analysis,
                            const Workspace::WorkspaceSnapshot& snapshot)
{
    json result{{"objectId", std::to_string(id.value())}, {"sessionId", std::to_string(snapshot.session.value())},
                {"revision", snapshot.revision}};
    if (analysis.mesh) {
        const auto& mesh = *analysis.mesh;
        result["mesh"] = {{"sizeMm", vector3(mesh.size)}, {"volumeMm3", std::round(mesh.volume * 100.0) / 100.0},
                          {"facets", mesh.facets}, {"parts", mesh.parts}, {"openEdges", mesh.open_edges},
                          {"repaired", {{"edgesFixed", mesh.edges_fixed}, {"degenerateFacets", mesh.degenerate_facets},
                                        {"facetsRemoved", mesh.facets_removed}, {"facetsReversed", mesh.facets_reversed},
                                        {"backwardsEdges", mesh.backwards_edges}}},
                          {"unitsSuspicion", mesh.units_suspicion.empty() ? "none" : mesh.units_suspicion},
                          {"partList", json::array()}};
        bool truncated = false;
        for (const auto& part : mesh.part_list)
            result["mesh"]["partList"].push_back({{"partId", std::to_string(part.id)}, {"name", label(part.name, truncated)},
                                                  {"kind", part.kind}, {"facets", part.facets}});
    }
    if (analysis.features) {
        json faces = json::array(), holes = json::array();
        for (const auto& face : analysis.features->faces)
            faces.push_back({{"handle", face.handle}, {"areaMm2", std::round(face.area * 100.0) / 100.0},
                             {"sizeMm", json::array({std::round(face.size[0] * 100.0) / 100.0, std::round(face.size[1] * 100.0) / 100.0})},
                             {"normal", vector3(face.normal)}, {"center", vector3(face.center)}});
        for (const auto& hole : analysis.features->holes)
            holes.push_back({{"handle", hole.handle}, {"diameterMm", std::round(hole.diameter * 10000.0) / 10000.0},
                             {"center", vector3(hole.center)}, {"axis", vector3(hole.axis)}});
        result["features"] = {{"faces", std::move(faces)}, {"holes", std::move(holes)}, {"truncated", analysis.features->truncated}};
    }
    if (analysis.fit) {
        json instances = json::array(), overlaps = json::array(), duplicates = json::array();
        for (const auto& instance : analysis.fit->instances) {
            json row{{"instance", instance.instance}, {"inside", instance.inside}};
            if (instance.plate) row["plateId"] = std::to_string(instance.plate->value());
            instances.push_back(std::move(row));
        }
        for (const auto& other : analysis.fit->overlaps) overlaps.push_back(std::to_string(other.value()));
        for (const auto& other : analysis.fit->likely_duplicates) duplicates.push_back(std::to_string(other.value()));
        result["fit"] = {{"instances", std::move(instances)}, {"overlaps", std::move(overlaps)},
                         {"likelyDuplicates", std::move(duplicates)}, {"truncated", analysis.fit->truncated}};
    }
    if (analysis.orientations) {
        json options = json::array();
        for (const auto& option : *analysis.orientations)
            options.push_back({{"up", vector3(option.up)}, {"unprintability", std::round(option.unprintability * 1000.0) / 1000.0},
                               {"overhangArea", std::round(option.overhang * 100.0) / 100.0},
                               {"bedContactMm2", std::round(option.bed_contact * 100.0) / 100.0},
                               {"facesDown", option.faces_down}});
        result["orientations"] = std::move(options);
    }
    if (analysis.measurement) {
        const auto& measured = *analysis.measurement;
        json row = json::object();
        if (measured.distance) row["distanceMm"] = std::round(*measured.distance * 10000.0) / 10000.0;
        if (measured.plane_distance) row["planeDistanceMm"] = std::round(*measured.plane_distance * 10000.0) / 10000.0;
        if (measured.angle) row["angleDegrees"] = std::round(*measured.angle * 1000.0) / 1000.0;
        if (measured.delta) row["deltaMm"] = vector3(*measured.delta);
        result["measurement"] = std::move(row);
    }
    return result;
}

json calibration_steps_result(const Workspace::CalibrationSteps& steps)

CommandResult OrcaWorkspaceAdapter::open_project(const ProjectOpenRequest& request, LoadReport& report)
{
    wxASSERT(wxIsMainThread());
    const boost::filesystem::path path(request.path);
    const std::string extension = boost::algorithm::to_lower_copy(path.extension().string());
    if (!request.new_project) {
        static const std::set<std::string> openable{".3mf", ".stl", ".obj", ".step", ".stp", ".amf", ".drc"};
        boost::system::error_code error;
        if (!path.is_absolute() || !boost::filesystem::is_regular_file(path, error))
            return CommandResult::failure(WorkspaceError::InvalidArgument, "Open an absolute path to a file that exists");
        if (openable.count(extension) == 0)
            return CommandResult::failure(WorkspaceError::InvalidArgument, "The app opens .3mf, .stl, .obj, .step, .amf and .drc files");
    }
    const ToolLoad tool_load(m_tool_loads);
    // Inside the load, the file listener answers and records; this catches
    // anything Orca asks around it.
    ScopedLeastChangeAnswers outside;

    // A model file opens as a new project named after it, as New and Import do.
    const bool model_file = !request.new_project && extension != ".3mf";
    const bool released   = release_project(model_file ? path.stem().string() : request.name);
    bool       loaded     = released;
    if (released && extension == ".3mf") {
        // "<loadall>" is Orca's own way to open a project with its settings
        // without asking how ("<silence>" would also leave the project
        // without its file name); geometry only is the answer the person
        // would otherwise give in ProjectDropDialog, set for this one load.
        if (request.load_project_settings) {
            m_plater.load_project(from_u8(request.path), "<loadall>");
        } else {
            AppConfig&        config   = *wxGetApp().app_config;
            const std::string previous = config.get(SETTING_PROJECT_LOAD_BEHAVIOUR);
            config.set(SETTING_PROJECT_LOAD_BEHAVIOUR, OPTION_PROJECT_LOAD_BEHAVIOUR_LOAD_GEOMETRY);
            m_plater.load_project(from_u8(request.path), "-");
            config.set(SETTING_PROJECT_LOAD_BEHAVIOUR, previous);
        }
        boost::system::error_code error;
        loaded = boost::filesystem::equivalent(into_path(m_plater.get_project_filename(".3mf")), path, error);
    } else if (released && model_file) {
        LoadStrategy strategy = LoadStrategy::LoadModel;
        if (request.units == UnitChoice::Inches)
            strategy = strategy | LoadStrategy::ImperialUnits;
        loaded = !m_plater.load_files(std::vector<boost::filesystem::path>{path}, strategy).empty();
    }

    report = take_load_report(/*started_by_agent=*/true);
    // A model file opens into the new project made just before its load.
    report.project_opened = true;
    add_outside_messages(report, outside.take_messages());
    if (!released)
        return CommandResult::failure(WorkspaceError::Failed, "The open project could not be saved, so it stays open");
    if (!loaded)
        return CommandResult::failure(WorkspaceError::Failed, "The app did not open that file");
    return CommandResult::success();
}

bool OrcaWorkspaceAdapter::release_project(const std::string& next_name)
{
    // Orca's new project releases the open one through the autosave hook,
    // which saves it, edited presets included, or cancels when it cannot.
    if (m_plater.new_project(true, true, from_u8(next_name)) == wxID_CANCEL)
        return false;
    // Orca asks about edited presets in UnsavedChangesDialog; once saved
    // they are dropped, so it is never asked. The values dropped were the
    // released project's, saved with it: none is an edit in the new one.
    m_dropping_released_edits = true;
    for (Preset::Type type : {Preset::TYPE_PRINTER, Preset::TYPE_PRINT, Preset::TYPE_FILAMENT})
        drop_unsaved_edits(wxGetApp().get_tab(type));
    m_dropping_released_edits = false;
    return true;
}


---IMPORT---
CommandResult OrcaWorkspaceAdapter::import_objects(const ImportRequest& request, LoadReport& report,
                                                   std::vector<ObjectId>& added)
{
    wxASSERT(wxIsMainThread());
    const boost::filesystem::path path(request.path);
    boost::system::error_code error;
    if (!path.is_absolute() || !boost::filesystem::is_regular_file(path, error) || boost::filesystem::file_size(path, error) == 0)
        return CommandResult::failure(WorkspaceError::InvalidArgument, "The model file does not exist");
    static const std::set<std::string> importable{".3mf", ".stl", ".obj", ".step", ".stp", ".amf", ".drc"};
    if (importable.count(boost::algorithm::to_lower_copy(path.extension().string())) == 0)
        return CommandResult::failure(WorkspaceError::InvalidArgument, "The app imports .stl, .obj, .step, .amf, .drc and .3mf files");
    PartPlateList& plates = m_plater.get_partplate_list();
    int plate = -1;
    if (request.plate) {
        for (int index = 0; index < plates.get_plate_count(); ++index)
            if (request.plate->session() == m_session && plates.get_plate(index)->id().id == request.plate->value())
                plate = index;
        if (plate < 0)
            return CommandResult::failure(WorkspaceError::NotFound, "That plate is not in the open project. Read workspace_inspect for the plate ids.");
    }

    std::vector<size_t> indices;
    const ToolLoad tool_load(m_tool_loads);
    ScopedLeastChangeAnswers outside;
    {
        // One coalesced, undoable change. LoadModel is the additive,
        // geometry-only strategy Import uses; a new object lands on the
        // current plate, so the target plate is selected first.
        ProjectStateTransaction transaction = m_plater.project_state_transaction();
        m_plater.take_snapshot("Import model");
        if (plate >= 0)
            m_plater.select_plate(plate);
        LoadStrategy strategy = LoadStrategy::LoadModel;
        if (request.units == UnitChoice::Inches)
            strategy = strategy | LoadStrategy::ImperialUnits;
        indices = m_plater.load_files(std::vector<boost::filesystem::path>{path}, strategy);
    }
    report = take_load_report(/*started_by_agent=*/true);
    add_outside_messages(report, outside.take_messages());
    if (indices.empty())
        return CommandResult::failure(WorkspaceError::Failed, "The app did not import that file");
    for (size_t index : indices) {
        const ObjectId id(m_session, m_plater.model().objects[index]->id().id);
        m_known_object_ids.insert(id.value());
        added.push_back(id);
    }
    return CommandResult::success(added.front());
}

CommandResult OrcaWorkspaceAdapter::delete_items(const std::vector<DeleteItem>& items)
{
    wxASSERT(wxIsMainThread());
    Model&         model  = m_plater.model();
    PartPlateList& plates = m_plater.get_partplate_list();
    std::vector<ItemForDelete> subitems;
    std::vector<std::size_t>   objects;
    std::vector<int>           plate_indices;
    std::map<std::size_t, std::pair<std::size_t, std::size_t>> removing; // object -> (model parts, instances)

    // Everything is checked first. Orca reports some refusals from these
    // paths with an error it shows after the call returns, which no answer
    // can reach, so the same conditions are refused here.
    for (const DeleteItem& item : items) {
        if (item.kind == DeleteItem::Kind::Plate) {
            int index = -1;
            for (int candidate = 0; candidate < plates.get_plate_count(); ++candidate)
                if (item.plate.session() == m_session && plates.get_plate(candidate)->id().id == item.plate.value())
                    index = candidate;
            if (index < 0)
                return CommandResult::failure(WorkspaceError::NotFound, "That plate is not in the open project. Read workspace_inspect for the plate ids.");
            plate_indices.push_back(index);
            continue;
        }
        const auto resolved = resolve(item.object);
        if (!resolved)
            return id_error(item.object);
        const ModelObject& object = *model.objects[resolved->index];
        if (item.kind == DeleteItem::Kind::Object) {
            objects.push_back(resolved->index);
        } else if (item.kind == DeleteItem::Kind::Part) {
            const auto volume = std::find_if(object.volumes.begin(), object.volumes.end(),
                                             [&](const ModelVolume* v) { return v->id().id == item.part; });
            if (volume == object.volumes.end())
                return CommandResult::failure(WorkspaceError::NotFound, "That part is not in " + object.name);
            if (object.is_cut() && ((*volume)->is_model_part() || (*volume)->is_negative_volume()))
                return CommandResult::failure(WorkspaceError::Refused,
                                              "The app does not delete the solid parts of a cut object");
            if ((*volume)->is_model_part())
                ++removing[resolved->index].first;
            subitems.emplace_back(itVolume, int(resolved->index), int(volume - object.volumes.begin()));
        } else {
            if (item.instance >= object.instances.size())
                return CommandResult::failure(WorkspaceError::InvalidArgument, object.name + " has no such copy");
            ++removing[resolved->index].second;
            subitems.emplace_back(itInstance, int(resolved->index), int(item.instance));
        }
    }
    std::sort(objects.begin(), objects.end());
    objects.erase(std::unique(objects.begin(), objects.end()), objects.end());
    // Parts and copies of an object that goes whole need no separate step.
    subitems.erase(std::remove_if(subitems.begin(), subitems.end(), [&](const ItemForDelete& item) {
                       return std::binary_search(objects.begin(), objects.end(), std::size_t(item.obj_idx));
                   }),
                   subitems.end());
    for (const auto& [index, counts] : removing) {
        if (std::binary_search(objects.begin(), objects.end(), index))
            continue;
        const ModelObject& object = *model.objects[index];
        const auto parts = std::count_if(object.volumes.begin(), object.volumes.end(), [](const ModelVolume* v) { return v->is_model_part(); });
        if (counts.first >= std::size_t(parts))
            return CommandResult::failure(WorkspaceError::InvalidArgument,
                                          "That would remove every solid part of " + object.name + "; delete the object instead");
        if (counts.second >= object.instances.size())
            return CommandResult::failure(WorkspaceError::InvalidArgument,
                                          "That would remove every copy of " + object.name + "; delete the object instead");
    }
    std::sort(plate_indices.begin(), plate_indices.end());
    plate_indices.erase(std::unique(plate_indices.begin(), plate_indices.end()), plate_indices.end());
    if (!plate_indices.empty() && plate_indices.size() >= std::size_t(plates.get_plate_count()))
        return CommandResult::failure(WorkspaceError::InvalidArgument, "A project keeps at least one plate");

    {
        const ProjectStateTransaction transaction = m_plater.project_state_transaction();
        Plater::TakeSnapshot snapshot(&m_plater, "Delete items");
        // The card named a cut object's broken correspondence already. Orca
        // asks before deleting a cut object and, on Delete, invalidates the
        // cut; doing that first is the same change, with nothing left to ask.
        for (std::size_t index : objects)
            if (model.objects[index]->is_cut())
                wxGetApp().obj_list()->invalidate_cut_info_for_object(int(index));
        // Nothing else should ask. If Orca does, the least change is taken
        // and logged, never shown in the middle of a tool call.
        ScopedLeastChangeAnswers unexpected;
        if (!subitems.empty()) {
            // The object list deletes in reverse order, so it gets them sorted.
            std::sort(subitems.begin(), subitems.end(), [](const ItemForDelete& a, const ItemForDelete& b) {
                return std::tie(a.obj_idx, a.type, a.sub_obj_idx) < std::tie(b.obj_idx, b.type, b.sub_obj_idx);
            });
            wxGetApp().obj_list()->delete_from_model_and_list(subitems);
        }
        for (auto index = objects.rbegin(); index != objects.rend(); ++index)
            if (!m_plater.delete_object(*index))
                // Orca refuses only an index out of range, or a cut object
                // whose question is declined; the cut info is cleared above.
                throw std::logic_error("OrcaSlicer did not delete an object the call checked");
        // A deleted plate's objects move to another plate, as in Orca.
        for (auto index = plate_indices.rbegin(); index != plate_indices.rend(); ++index)
            m_plater.delete_plate(*index);
        m_plater.notify_project_state_changed(ProjectStateChangeReason::Objects | ProjectStateChangeReason::Plates);
        for (const OrcaMessage& message : unexpected.messages())
            BOOST_LOG_TRIVIAL(warning) << "delete_items: OrcaSlicer asked \"" << message.title << "\" (" << message.text
                                       << "), answered " << message.answer;
    }
    return CommandResult::success();
}

